// The model and effort rules for a subagent. Pure functions: the module
// reads the agent file and the spawn input, and passes them here.

import { SUBAGENT_EFFORTS } from "../budget.mjs";

/** `model` and `effort` from the front matter of an agent file's text. */
export function parseDefinition(text) {
  const head = text.split(/^---\s*$/m)[1] ?? "";
  return {
    model: /^model:\s*(\S+)\s*$/m.exec(head)?.[1] ?? "",
    effort: /^effort:\s*(\S+)\s*$/m.exec(head)?.[1] ?? "",
  };
}

/** The model that an agent file fixes, or "" for `inherit` or no model. */
export const pinnedModel = (def) =>
  def?.model && def.model !== "inherit" ? def.model : "";

// The bare aliases name the current model of each family.
const ALIASES = {
  opus: "opus-5-5",
  sonnet: "sonnet-5-5",
  haiku: "haiku-4-5",
  fable: "fable-5-1",
};

/**
 * A key for a model name: `claude-sonnet-5-5`, `sonnet-5-5[1m]`, and a name
 * with a date suffix give `sonnet-5-5`. An alias gives its current model.
 */
export function modelKey(name) {
  const key = String(name ?? "")
    .toLowerCase()
    .replace(/\[.*\]$/, "")
    .replace(/^claude-/, "")
    .replace(/-\d{8}$/, "")
    .replace(/\./g, "-");
  return ALIASES[key] ?? key;
}

const code = (list) => list.map((x) => `\`${x}\``).join(", ");
const allowedModels = () => code(Object.keys(SUBAGENT_EFFORTS));

/**
 * The reason to deny a spawn, or undefined.
 * `askedModel` is the `model` of the call, `parentModel` is the model of the
 * caller, `pinned` is the model of the agent file, and `effort` is the effort
 * that the agent runs with. A call with no `model` runs on `pinned`, and
 * without that on `parentModel`.
 */
export function spawnDenial({ askedModel, parentModel, pinned, effort }) {
  if (askedModel && pinned && modelKey(askedModel) !== modelKey(pinned))
    return `This agent is fixed to the model \`${pinned}\`, and the call asked for \`${askedModel}\`. Omit \`model\`, or pick the agent whose model you need.`;
  const model = pinned || askedModel || parentModel;
  // The spawn names no model and the engine gave none: nothing to check.
  if (!model) return undefined;
  const key = modelKey(model);
  const efforts = SUBAGENT_EFFORTS[key];
  if (!efforts)
    return `A subagent cannot run on \`${model}\`. The allowed models are ${allowedModels()}. Pick an agent that fixes one of them.`;
  if (effort && !efforts.includes(effort))
    return efforts.length
      ? `The effort \`${effort}\` is not allowed for \`${key}\`. The allowed efforts are ${code(efforts)}.`
      : `\`${key}\` takes no effort, and the effort is \`${effort}\`. Remove the effort.`;
  return undefined;
}

files.lib/guards/attribution.mjs:
// Git attribution. Claude Code sends its `Co-Authored-By` trailer and pull
// request footer only with its built-in git instructions, and the setup
// profile turns those off (`includeGitInstructions: false`). The session note
// puts the lines back in a repository of the user or of an organization that
// the user owns, from the same settings that Claude Code reads. A repository
// with a remote of another owner gets no lines, because the AI policy of that
// project decides. The Bash guard denies a Claude trailer that the settings
// leave out (Claude adds it from habit, claude-code #4287 and #93007), and it
// asks before a Claude attribution line in a repository of another owner.
// These functions are pure, because the hooks module has no Node. The callers
// read the files and run the commands.

import { clause, clauseTag } from "../terms.mjs";

const PR_FOOTER =
  "🤖 Generated with [Claude Code](https://claude.com/claude-code)";

export const OTHER_OWNER_NOTE = `${clauseTag("git-attribution")}
<git_attribution source="dotclaude">
This repository has a remote of another owner, so the AI policy of that project decides the attribution.
Before a commit or a pull request, read the policy, such as \`CONTRIBUTING.md\` or \`AI_POLICY.md\`, and use only the attribution form that it asks for.
When the policy says nothing, add no Claude \`Co-Authored-By\` line and no Claude Code footer.
For an issue, a pull request, or a comment, use the \`dotclaude:contribute\` skill.
</git_attribution>
</dotclaude_terms>`;

export const TRAILER_OFF_REASON =
  "The commit message has a Claude `Co-Authored-By` line, but the attribution settings of the user leave it out. Remove the line, then commit again. This is clause 3 of the dotclaude Terms of Use.";

export const OTHER_OWNER_REASON =
  "The commit message has a Claude attribution line, and this repository has a remote of another owner. The AI policy of that project decides if the line can stay. This is clause 3 of the dotclaude Terms of Use.";

export const CLAUDE_TRAILER =
  /(^|[\s"'])co-authored-by:[^\n]*(claude|anthropic)/im;
const CLAUDE_ATTRIBUTION =
  /(^|[\s"'])((co-authored|co-developed|assisted|generated)-by:[^\n]*(claude|anthropic)|generated with \[?claude code)/im;

/** True when `text` has a Claude attribution line of any form. */
export const hasClaudeAttribution = (text) => CLAUDE_ATTRIBUTION.test(text);

export const LOGIN_ARGV = ["gh", "config", "get", "user", "-h", "github.com"];
// GitHub records no organization creator, so the owner role (`admin`) stands
// for it. This call goes to the network, so the callers run it only when a
// remote is not under the login.
export const ORGS_ARGV = [
  "gh",
  "api",
  "user/memberships/orgs",
  "--paginate",
  "--jq",
  '.[] | select(.role == "admin" and .state == "active") | .organization.login',
];

/** The lines of a command output, without empty lines. */
export const linesOf = (text) =>
  (text ?? "")
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);

/** The user, project, and local settings files, in the order that they win. */
export const settingsPaths = (configDir, root) => [
  `${configDir}/settings.json`,
  `${root}/.claude/settings.json`,
  `${root}/.claude/settings.local.json`,
];

/** The settings texts, merged key by key; later texts win. */
export function mergeSettings(texts) {
  const merged = {};
  for (const text of texts) {
    try {
      const s = JSON.parse(text);
      for (const key of ["includeGitInstructions", "includeCoAuthoredBy"])
        if (key in s) merged[key] = s[key];
      if (s.attribution && typeof s.attribution === "object")
        merged.attribution = { ...merged.attribution, ...s.attribution };
    } catch {
      // Missing or unreadable: Claude Code skips it too.
    }
  }
  return merged;
}

/** `Claude Opus 5.5` for `claude-opus-5-5`, and `Claude` for other names. */
export function modelName(model = "") {
  const m = /^claude-(opus|sonnet|haiku)-(\d+)-(\d)\b/.exec(model);
  return m
    ? `Claude ${m[1][0].toUpperCase()}${m[1].slice(1)} ${m[2]}.${m[3]}`
    : "Claude";
}

/**
 * True when each line of `git remote -v` is a GitHub remote of one of
 * `owners`. A fork with an `upstream` of another owner is not the user's own.
 */
export function ownRepo(remotes, owners) {
  const own = new RegExp(`github\\.com[:/](${owners.join("|")})/`, "i");
  return remotes
    .split("\n")
    .every((line) => !line || (owners.length > 0 && own.test(line)));
}

/**
 * True when the settings leave the Claude trailer out of commits: an
 * `attribution.commit` without it, or `includeCoAuthoredBy: false`.
 */
export function trailerOff(s) {
  if (s.attribution)
    return (
      typeof s.attribution.commit === "string" &&
      !CLAUDE_TRAILER.test(s.attribution.commit)
    );
  return s.includeCoAuthoredBy === false;
}

/** The note for a repository of the user, or null when Claude Code sends its own. */
export function attributionNote(model, s) {
  if (s.includeGitInstructions !== false) return null;
  // Claude Code 2.1.289 gives no `model` to a SessionStart command hook, and
  // `/model` can change it later, so then Claude writes the name of its model.
  const name = modelName(model);
  let commit = `Co-Authored-By: ${name === "Claude" ? "<model>" : name} <noreply@anthropic.com>`;
  let pr = PR_FOOTER;
  if (s.attribution) ({ commit = commit, pr = pr } = s.attribution);
  else if (s.includeCoAuthoredBy === false) commit = pr = "";
  const lines = [];
  if (commit)
    lines.push(
      commit.includes("<model>")
        ? `End each commit message with a blank line, then this text, with \`<model>\` changed to the name of the model that you run on, such as \`Claude Opus 5.5\`:\n${commit}`
        : `End each commit message with a blank line, then this text exactly:\n${commit}`,
    );
  if (pr)
    lines.push(
      `End each pull request body with a blank line, then this text exactly:\n${pr}`,
    );
  return lines.length
    ? clause(
        "git-attribution",
        `<git_attribution source="dotclaude">\n${lines.join("\n")}\n</git_attribution>`,
      )
    : null;
}

files.lib/guards/bash.mjs:
// Bash guard rules. `askFor(command, ctx)` gives one finding for each part of
// a command that needs the user's approval, as `{ part, reason }`.
// The tokenizer is small on purpose. It splits on `&&`, `||`, `;`, `|`, `&`,
// newlines, parentheses, and backticks, and it keeps quoted text in one word.
// It reads the script of `bash -c` and `sh -c` one level deep.

import { COMMAND_PART_CHARS } from "../budget.mjs";
import { TERMS } from "../terms.mjs";

const CODEGRAPH_CLAUSE = `This is clause ${TERMS.findIndex((t) => t.id === "codegraph-index") + 1} of the dotclaude Terms of Use.`;

/** The parts of `command`, each as a list of words. */
export function tokenize(command) {
  const parts = [];
  let words = [];
  let word = null;
  let quote = null;
  const endWord = () => {
    if (word !== null) words.push(word);
    word = null;
  };
  const endPart = () => {
    endWord();
    if (words.length) parts.push(words);
    words = [];
  };
  for (let i = 0; i < command.length; i += 1) {
    const c = command[i];
    if (quote) {
      if (c === quote) quote = null;
      else if (c === "\\" && quote === '"' && i + 1 < command.length) {
        i += 1;
        word += command[i];
      } else word += c;
    } else
      switch (c) {
        case "'":
        case '"':
          quote = c;
          word ??= "";
          break;
        case "\\":
          i += 1;
          word = (word ?? "") + (command[i] ?? "");
          break;
        case " ":
        case "\t":
          endWord();
          break;
        default:
          if (";|&\n()`".includes(c)) endPart();
          else word = (word ?? "") + c;
      }
  }
  endPart();
  return parts;
}

const SHELLS = new Set(["bash", "sh", "zsh", "dash"]);

/** The parts of `command`, with the script of each `sh -c` one level deep. */
function partsOf(command, depth = 0) {
  const out = [];
  for (const words of tokenize(command)) {
    out.push(words);
    const at = words.findIndex((w) => /^-[a-z]*c[a-z]*$/.test(w));
    const script = words[at + 1];
    if (depth === 0 && SHELLS.has(base(words[0])) && at > 0 && script)
      out.push(...partsOf(script, 1));
  }
  return out;
}

const base = (word = "") => word.split("/").pop();
const WRAPPERS = new Set(["env", "command", "nohup", "time", "exec"]);

/** True when `args` has the long flag, or a letter of `short` in a short group. */
function hasFlag(args, long, short = "") {
  return args.some(
    (a) =>
      a === long ||
      a.startsWith(`${long}=`) ||
      (/^-[^-]/.test(a) && [...short].some((c) => a.includes(c))),
  );
}

const GIT_VALUE_FLAGS = new Set(["-C", "-c", "--git-dir", "--work-tree"]);

/** The index of the git subcommand in `words`. */
function gitSub(words) {
  let i = 1;
  while (words[i]?.startsWith("-")) i += GIT_VALUE_FLAGS.has(words[i]) ? 2 : 1;
  return i;
}

/** `words` with no leading variable, wrapper, or `sudo`. */
function commandWords(words) {
  while (
    /^[A-Za-z_]\w*=/.test(words[0] ?? "") ||
    WRAPPERS.has(base(words[0])) ||
    base(words[0]) === "sudo"
  )
    words = words.slice(1);
  return words;
}

/** True when a part of `command` is `git commit`. */
export function isCommit(command) {
  return partsOf(command).some((raw) => {
    const words = commandWords(raw);
    return base(words[0]) === "git" && words[gitSub(words)] === "commit";
  });
}

const DISCARD =
  "This command discards the uncommitted changes in the named files, and git cannot restore them.";
// A word that names a file and not a branch: a path with an extension, a
// relative path, or a glob.
const PATH_LIKE = /(^\.{1,2}(\/|$)|\.[A-Za-z]\w*$|[*?])/;

/**
 * True when `git checkout <args>` overwrites files in the work tree: with
 * `--force`, with paths after `--`, with a ref and a path, or with one word
 * that looks like a path. A branch switch keeps uncommitted changes.
 */
function checkoutDiscards(args) {
  if (hasFlag(args, "--force", "f")) return true;
  const dash = args.indexOf("--");
  if (dash >= 0) return dash < args.length - 1;
  if (hasFlag(args, "--orphan", "bB")) return false;
  const words = args.filter((a) => !a.startsWith("-"));
  return words.length > 1 || PATH_LIKE.test(words[0] ?? "");
}

const SKIP_HOOKS = "This command skips the git hooks of the project.";
// Environment values that turn off the hooks of Husky, Lefthook, and pre-commit.
const HOOKS_OFF_ENV = /^(HUSKY=0|LEFTHOOK=0|SKIP=.+)$/;

function gitReason(words, env) {
  const i = gitSub(words);
  const sub = words[i];
  const args = words.slice(i + 1);
  if (
    hasFlag(args, "--no-verify", sub === "commit" ? "n" : "") ||
    words.slice(1, i).some((w) => /^core\.hooksPath=/i.test(w)) ||
    env.some((w) => HOOKS_OFF_ENV.test(w))
  )
    return SKIP_HOOKS;
  switch (sub) {
    case "push":
      if (
        hasFlag(args, "--force", "f") ||
        hasFlag(args, "--force-with-lease") ||
        hasFlag(args, "--force-if-includes") ||
        args.some((a) => a.startsWith("+"))
      )
        return "A forced push can replace commits on the remote.";
      break;
    case "reset":
      if (args.includes("--hard"))
        return "A hard reset removes all uncommitted changes.";
      break;
    case "clean":
      if (hasFlag(args, "--force", "f") && !hasFlag(args, "--dry-run", "n"))
        return "This command deletes untracked files for good.";
      break;
    case "checkout":
      if (checkoutDiscards(args)) return DISCARD;
      break;
    case "restore":
      if (
        args.some((a) => !a.startsWith("-")) &&
        !(hasFlag(args, "--staged", "S") && !hasFlag(args, "--worktree", "W"))
      )
        return DISCARD;
      break;
    case "branch":
      if (args.some((a) => /^-[a-zA-Z]*D/.test(a)))
        return "This command deletes a branch even when it is not merged.";
      break;
    default:
  }
  return undefined;
}

/** The absolute path of `target`, with `.` and `..` resolved. */
function resolve(target, cwd) {
  const out = [];
  const full = target.startsWith("/") ? target : `${cwd}/${target}`;
  for (const part of full.split("/")) {
    if (part === "..") out.pop();
    else if (part && part !== ".") out.push(part);
  }
  return `/${out.join("/")}`;
}

const inside = (path, root) => path === root || path.startsWith(`${root}/`);

/** The reason that `rm -r` of `target` needs approval, if it does. */
function removeReason(target, { project, cwd, home }) {
  const t = target.replace(/^(~|\$HOME|\$\{HOME\})(?=\/|$)/, home ?? "\0");
  if (t.startsWith("\0")) return "The home folder of the user is not known.";
  if (t.includes("$")) return "The target is known only at run time.";
  const path = resolve(t, cwd);
  if (path === "/") return "This command deletes the root folder.";
  if (path === home) return "This command deletes the home folder.";
  if (!project) return "The project folder is not known.";
  if (path === project) return "This command deletes the project folder.";
  if (!inside(path, project)) return "The target is outside the project.";
  return undefined;
}

const READERS = new Set(
  "cat less more head tail bat nl tac xxd od strings grep rg awk sed base64 cut sort diff".split(
    " ",
  ),
);
const SECRET_FILE = [
  /(^|\/)\.env(\.[\w.-]+)?$/,
  /(^|\/)\.ssh\/id_[\w-]+$/,
  /(^|\/)\.aws\/credentials$/,
];
const ENV_TEMPLATE = /\.(example|sample|template|dist)$/;

const isSecretFile = (word) =>
  SECRET_FILE.some((re) => re.test(word)) && !ENV_TEMPLATE.test(word);

// `gh` groups that change GitHub, and the verbs in them that only read.
const GH_GROUPS = new Set(
  "pr issue release repo gist secret variable workflow run label project ruleset cache".split(
    " ",
  ),
);
const GH_READS = new Set(
  "list view status diff checks download watch clone checkout".split(" "),
);
const GH_WRITE =
  "This command writes to GitHub, where other people can see it.";

function ghReason(args) {
  const [sub, verb] = args.filter((a) => !a.startsWith("-"));
  if (sub === "api") {
    // A GraphQL query is sent as a POST field but only reads,
    // so only a mutation, or a query from a file or stdin that the guard cannot read, asks.
    if (args.includes("graphql"))
      return args.some((a) => /\bmutation\b|^query=@|^--input/.test(a))
        ? GH_WRITE
        : undefined;
    const i = args.findIndex((a) => /^(-X|--method)$/.test(a));
    const inline = args.find((a) => /^(-X.|--method=)/.test(a));
    const method = (
      i >= 0
        ? (args[i + 1] ?? "")
        : (inline?.replace(/^(-X|--method=)/, "") ?? "")
    ).toUpperCase();
    const fields =
      hasFlag(args, "--input", "fF") ||
      hasFlag(args, "--field") ||
      hasFlag(args, "--raw-field");
    return (method ? method !== "GET" : fields) ? GH_WRITE : undefined;
  }
  if (GH_GROUPS.has(sub) && verb && !GH_READS.has(verb)) return GH_WRITE;
  return undefined;
}

const PUBLISH =
  "This command publishes a package or an image, and a publish is hard to undo.";
const DRY_RUN = (args) => hasFlag(args, "--dry-run");

function publishReason(name, args) {
  const [sub, next] = args.filter((a) => !a.startsWith("-"));
  const found =
    (["npm", "pnpm", "bun"].includes(name) &&
      ["publish", "unpublish", "deprecate"].includes(sub)) ||
    (name === "yarn" &&
      (sub === "publish" || (sub === "npm" && next === "publish"))) ||
    (name === "cargo" && ["publish", "yank"].includes(sub)) ||
    (name === "gem" && ["push", "yank"].includes(sub)) ||
    (name === "twine" && sub === "upload") ||
    (["poetry", "uv", "vsce", "ovsx"].includes(name) && sub === "publish") ||
    (["docker", "podman"].includes(name) && sub === "push") ||
    (name === "dotnet" && sub === "nuget" && next === "push");
  return found && !DRY_RUN(args) ? PUBLISH : undefined;
}

const DB_DELETE = "This command deletes data in a database.";
const DB_CLIENTS = new Set(
  "psql mysql mariadb sqlite3 sqlcmd mongosh mongo redis-cli clickhouse-client".split(
    " ",
  ),
);
const DESTRUCTIVE_SQL =
  /\b(drop\s+(table|database|schema|index|view|collection)|truncate|delete\s+from|flushall|flushdb|dropdatabase|deletemany)\b|\.drop\(/i;

function databaseReason(name, args) {
  if (DB_CLIENTS.has(name) && args.some((a) => DESTRUCTIVE_SQL.test(a)))
    return DB_DELETE;
  if (name === "dropdb") return DB_DELETE;
  if (name === "mysqladmin" && args.includes("drop")) return DB_DELETE;
  const [sub, next] = args.filter((a) => !a.startsWith("-"));
  if (
    name === "prisma" &&
    ((sub === "migrate" && next === "reset") || hasFlag(args, "--force-reset"))
  )
    return DB_DELETE;
  if (
    ["rails", "rake"].includes(name) &&
    /^db:(drop|reset|schema:load)$/.test(sub ?? "")
  )
    return DB_DELETE;
  if (/manage\.py$/.test(name) && sub === "flush") return DB_DELETE;
  return undefined;
}

// `npx`, `bunx`, and `python manage.py` run another tool,
// so the guard reads the tool that they run.
function runnerTarget(name, args) {
  if (["npx", "bunx"].includes(name))
    return args.filter((a) => !a.startsWith("-"));
  if (["python", "python3"].includes(name) && /manage\.py$/.test(args[0] ?? ""))
    return args;
  return undefined;
}

/** The reason for one part, or undefined. `words` has no leading `sudo`. */
function reasonFor(words, ctx, env = []) {
  const name = base(words[0]);
  const args = words.slice(1);
  const inner = runnerTarget(name, args);
  if (inner?.length) return reasonFor(inner, ctx, env);
  const other =
    (name === "gh" && ghReason(args)) ||
    publishReason(name, args) ||
    databaseReason(name, args);
  if (other) return other;
  switch (name) {
    case "git":
      return gitReason(words, env);
    case "rm":
      if (hasFlag(args, "--recursive", "rR")) return rmReason(args, ctx);
      break;
    case "dd":
      if (args.some((a) => a.startsWith("of=/dev/")))
        return "This command writes straight to a device.";
      break;
    case "chmod":
      if (
        hasFlag(args, "--recursive", "R") &&
        args.some((a) => /^(0?777|a\+rwx|ugo\+rwx)$/.test(a))
      )
        return "This command makes a whole tree writable for all users.";
      break;
    case "codegraph":
      switch (args[0]) {
        case "init":
          return `This command builds a CodeGraph index of the project in a \`.codegraph/\` folder. ${CODEGRAPH_CLAUSE}`;
        case "uninit":
          return `This command deletes the CodeGraph index of the project. ${CODEGRAPH_CLAUSE}`;
      }
      break;
  }
  if (name === "mkfs" || name.startsWith("mkfs."))
    return "This command erases the data of a device.";
  if (READERS.has(name) && args.some(isSecretFile))
    return "This command reads a file that can hold secrets.";
  return undefined;
}

// Each flagged target gets its own reason, because a harmless first target
// once hid a `"${TMPDIR}"tmp.*` target that deleted the temporary folders of other programs.
function rmReason(args, ctx) {
  const found = args
    .filter((a) => !a.startsWith("-"))
    .map((target) => [target, removeReason(target, ctx)])
    .filter(([, reason]) => reason);
  if (found.length < 2) return found[0]?.[1];
  return found.map(([target, reason]) => `\`${target}\`: ${reason}`).join(" ");
}

/**
 * One finding for each part of `command` that needs approval. `ctx` holds
 * `project` (the project folder), `cwd`, and `home`.
 */
export function askFor(command, ctx) {
  const findings = [];
  for (const raw of partsOf(command)) {
    let words = raw;
    let sudo = false;
    const env = [];
    for (;;) {
      while (/^[A-Za-z_]\w*=/.test(words[0] ?? "")) {
        env.push(words[0]);
        words = words.slice(1);
      }
      if (WRAPPERS.has(base(words[0]))) words = words.slice(1);
      else if (base(words[0]) === "sudo") {
        sudo = true;
        words = words.slice(1);
      } else break;
    }
    if (!words.length) continue;
    const reason = sudo
      ? "This command runs as the root user."
      : reasonFor(words, ctx, env);
    if (reason) findings.push({ part: partText(raw), reason });
  }
  return findings;
}

const BASH_WRITE = `This command writes a project file through \`Bash\`. Edit a project file with \`Edit\` or \`Write\`, because these tools show the user a diff, Claude Code checkpoints can rewind them, and the dotclaude edit guard checks them. A \`Bash\` write skips all of these. Put a temporary file in \`$TMPDIR\`. This is clause ${TERMS.findIndex((t) => t.id === "working-rules") + 1} of the dotclaude Terms of Use.`;
// The auto-mode text of Claude Code 2.1.290 tells Claude to edit files with `sed`, heredocs,
// or scripts (binary, `case "auto_mode"`).
const AUTO_MODE_EDIT_TEXT =
  /(?:Do your work|You can do much of your work) through the \S+ tool [\s\S]*?(?:cannot do the job\.|BSD\/macOS\.)/;
const AUTO_MODE_EDITS = `Read and search with \`Bash\` when it is the simpler route. Edit a project file only with \`Edit\` or \`Write\`, because a \`Bash\` write skips the diff, the checkpoints, and the dotclaude edit guard. The dotclaude Bash guard denies a \`Bash\` write to a project file.`;

/** The auto-mode `text` with the dotclaude edit rule in place of the `Bash` edit text. */
export const autoModeText = (text) =>
  text.replace(AUTO_MODE_EDIT_TEXT, AUTO_MODE_EDITS);

const TEMP_ROOTS = [
  "/tmp",
  "/private/tmp",
  "/var/folders",
  "/private/var/folders",
];

/**
 * True when a write to `target` changes a file in the project.
 * A target with `$` is known only at run time, so it passes.
 */
function projectFile(target, { project, cwd, home, tmp }) {
  if (!target || !project || target.includes("$")) return false;
  const t = target.replace(/^~(?=\/|$)/, home ?? "\0");
  if (t.startsWith("\0")) return false;
  const path = resolve(t, cwd);
  if (path.startsWith("/dev/")) return false;
  if ([...TEMP_ROOTS, tmp].some((r) => r && inside(path, resolve(r, "/"))))
    return false;
  return inside(path, project);
}

/** `command` with the body of each heredoc removed, because a body is data. */
function withoutHeredocs(command) {
  const out = [];
  let end = null;
  for (const line of command.split("\n")) {
    if (end !== null) {
      if (line.trim() === end) end = null;
      continue;
    }
    out.push(line);
    end = /(?<!<)<<(?!<)-?\s*(['"]?)([\w.-]+)\1/.exec(line)?.[2] ?? null;
  }
  return out.join("\n");
}

/** The files that `sed -i` or `perl -i` changes, from its `args`. */
function inPlaceTargets(name, args) {
  const inPlace = ["sed", "gsed"].includes(name)
    ? hasFlag(args, "--in-place", "i")
    : name === "perl" && args.some((a) => /^-[a-zA-Z]*i/.test(a));
  if (!inPlace) return [];
  const files = [];
  let script = false;
  for (let i = 0; i < args.length; i += 1) {
    if (/^(-[ef]|--expression|--file)$/.test(args[i])) {
      script = true;
      i += 1;
    } else if (args[i] && !args[i].startsWith("-")) files.push(args[i]);
  }
  // With no `-e`, the first word is the script.
  return script ? files : files.slice(1);
}

/** The redirect targets in `words`: `> f`, `>> f`, `2>f`, and `>f`. */
function redirectTargets(words) {
  return words.flatMap((w, i) => {
    const m = /^\d*>>?(.*)$/.exec(w);
    if (!m) return [];
    const target = m[1] || words[i + 1];
    return target ? [target] : [];
  });
}

/** The files of `tee`, before the first redirect in `args`. */
function teeTargets(args) {
  const end = args.findIndex((a) => /^\d*[<>]/.test(a));
  return args
    .slice(0, end < 0 ? undefined : end)
    .filter((a) => !a.startsWith("-"));
}

const INTERPRETERS = new Set(
  "python python3 node bun deno ruby perl".split(" "),
);
// Write calls of script code.
// Group 2 is the path when it is a literal.
const WRITE_CALLS = [
  /\bopen\(\s*(?:(["'])([^"'\n]*)\1|[^,()\n]*)\s*,\s*(?:mode\s*=\s*)?["'][rbt]*[wax+][rwabxt+]*["']/g,
  /(?:\bPath\(\s*(["'])([^"'\n]*)\1\s*\))?\.write_(?:text|bytes)\(/g,
  /\b(?:writeFileSync|writeFile|appendFileSync|appendFile|createWriteStream|Bun\.write|Deno\.writeTextFile|Deno\.writeFile|File\.write|IO\.write)\(\s*(?:(["'`])([^"'`\n]*)\1)?/g,
];
const PATH_LITERAL = /(["'])([^"'\n$]*\/[^"'\n$]*|[^"'\n$/]*\.[A-Za-z]\w*)\1/g;

/**
 * The files that script code in `command` writes.
 * When a write call has no literal path, each path literal in the code counts.
 */
function scriptTargets(command) {
  const calls = WRITE_CALLS.flatMap((re) =>
    [...command.matchAll(re)].map((m) => m[2] ?? null),
  );
  if (calls.every((t) => t !== null)) return calls;
  return [...command.matchAll(PATH_LITERAL)]
    .map((m) => m[2])
    .filter((p) => !/^\w+:\/\//.test(p));
}

/**
 * One finding for each part of `command` that writes a file in the project:
 * a redirect, `tee`, `sed -i`, `perl -i`, or script code with a write call.
 * `ctx` holds `project`, `cwd`, `home`, and `tmp`.
 */
export function writeFor(command, ctx) {
  const findings = [];
  for (const raw of partsOf(withoutHeredocs(command))) {
    const words = commandWords(raw);
    const name = base(words[0]);
    const targets = [
      ...redirectTargets(raw),
      ...(name === "tee" ? teeTargets(words.slice(1)) : []),
      ...inPlaceTargets(name, words.slice(1)),
    ];
    if (targets.some((t) => projectFile(t, ctx)))
      findings.push({ part: partText(raw), reason: BASH_WRITE });
  }
  const scripted = partsOf(command).find((raw) =>
    INTERPRETERS.has(base(commandWords(raw)[0])),
  );
  if (
    scripted &&
    !findings.length &&
    scriptTargets(command).some((t) => projectFile(t, ctx))
  )
    findings.push({ part: partText(scripted), reason: BASH_WRITE });
  return findings;
}

const partText = (words) => {
  const text = words.join(" ");
  return text.length > COMMAND_PART_CHARS
    ? `${text.slice(0, COMMAND_PART_CHARS)}...`
    : text;
};

